import {CHARACTERS,STAGES,byId} from './data.js?v=1.7.9';
import {SLOTS,GRADES,GRADE_IDS,STAT_NAMES,UNIQUE_OPTIONS,REROLL_COST,craftCandidates,extraRange,PERCENT_STATS,gearName,formatOption,optionRange,isEquipped,calculateStats,applyUnitStats,damageReduction,dropRates,drawRates,enhancedBase,ENHANCE_CHANCES} from './equipment.js?v=1.7.9';
import {icon} from './art.js?v=1.7.9';

export const newGearView=()=>({tab:'bag',slot:'all',grade:'all',selected:null,page:0,craftMaterials:[]});
const pct=n=>`${Number((n*100).toFixed(2))}%`;
const slotFor=item=>SLOTS.find(s=>s.id===item.slot);
const statValue=(key,value)=>['rate','ability'].includes(key)?`${value.toFixed(2)}×`:key==='regen'?`${value.toFixed(2)}/s`:Number(value.toFixed(1));
const STAT_ROWS=[['attack','공격력'],['defense','방어력'],['hp','최대 체력'],['magic','마력'],['speed','이동 속도'],['rate','공격 속도'],['ability','초능력 배율'],['regen','체력 재생'],['strength','힘'],['intelligence','지능'],['agility','민첩']];
const STAT_DESCRIPTIONS={attack:'기본 공격 피해를 높입니다. 공격 초능력은 1 + log₂(1 + 공격력 ÷ 20) ÷ 2의 완만한 배율을 적용합니다.',defense:'받는 피해를 방어력 ÷ (100 + 방어력)만큼 줄입니다.',hp:'캐릭터가 보유할 수 있는 최대 체력입니다.',magic:'마법 초능력은 마력의 제곱근을 피해 배율로 적용합니다.',speed:'캐릭터의 이동 속도입니다.',rate:'기본 공격은 전체 배율, 공격 초능력은 제곱근 배율로 주기가 빨라집니다. 마법 초능력에는 적용되지 않습니다.',ability:'공격·마법 초능력 피해에는 제곱근 배율을 적용합니다. 회복 계열은 각 능력 설명을 따릅니다. 시간 정지·정신 장벽·신경 가속은 제외됩니다.',regen:'초당 회복되는 기본 체력입니다. 초능력 회복은 별도로 적용됩니다.',strength:'기본 힘 1당 공격력이 1% 증가합니다.',intelligence:'기본 지능 1당 마력 배율이 1% 증가합니다.',agility:'민첩 1당 이동 속도 0.5%, 공격 속도 0.3%가 증가합니다.',pickup:'경험치와 아이템을 끌어오는 범위입니다.',xp:'경험치 획득 배율입니다. 에테르 덩어리 하나당 최대 20 경험치를 얻습니다.',area:'폭발·파동·중력장·위성 등 적용 대상의 공격 범위 배율입니다.',cooldown:'초능력 주기에 곱해지는 배율입니다. 낮을수록 빨리 사용하며 최저 0.2배입니다.',regenBoost:'기본 재생과 회복 계열 초능력에 적용되는 재생 강화 배율입니다.'};
function statsHelp(stats,reduction){const extra=[['pickup','획득 범위'],['xp','경험치 획득'],['area','공격 범위'],['cooldown','재사용시간'],['regenBoost','재생 강화']];return `<details class="stats-explainer"><summary>능력치 상세 설명</summary><div class="stats-explainer-body"><p>표시된 수치는 현재 장비·연구와 이번 전투의 능력을 반영합니다.</p>${[...STAT_ROWS,...extra].map(([key,label])=>`<div><strong>${label}</strong><span>${STAT_DESCRIPTIONS[key]}</span></div>`).join('')}<div><strong>총 피해 감소 ${pct(reduction.total)}</strong><span>방어 ${pct(reduction.defense)}와 초능력 ${pct(reduction.skill)}은 남은 피해에 순서대로 적용하고, 장비 ${pct(reduction.gear)}p를 더합니다. 최종 상한은 95%입니다.</span></div></div></details>`;}
export function fusionMarkup(recipes,skills,owned={}){return `<div class="fusion-recipes">${recipes.map(r=>{const output=byId(skills,r.id);return `<div class="fusion-recipe" style="--skill-color:${output.color}"><span class="skill-symbol">${output.icon}</span><div><strong>${output.name}</strong><p>${r.ingredients.map(id=>{const s=byId(skills,id),level=owned[r.id]?r.level:Math.min(r.level,owned[id]||0);return `<span class="${level>=r.level?'fusion-ready':''}">${s.name} <b>${level}/${r.level}</b></span>`;}).join(' + ')}</p><small>${owned[r.id]?'융합 완료 · 원본 능력이 하나로 합쳐졌습니다':'각각 Lv.10 달성 후 레벨업 선택지에서 융합 · 장비를 소비하지 않습니다'}</small></div></div>`;}).join('')}</div>`;}
const formatEnhanced=item=>PERCENT_STATS.has(item.base.stat)?`${STAT_NAMES[item.base.stat]} +${pct(enhancedBase(item))}`:formatOption(item.base.stat,enhancedBase(item));
function itemCard(item,save,ui){const grade=GRADES[item.rarity],equipped=isEquipped(save,item.uid);return `<button class="gear-card ${ui.selected===item.uid?'selected':''}" style="--gear-color:${grade.color}" data-action="gear-select" data-id="${item.uid}" aria-pressed="${ui.selected===item.uid}" aria-label="${gearName(item)} ${item.rarity.toUpperCase()} ${equipped?'장착 중':'미장착'}"><div><span class="grade-label">${item.rarity.toUpperCase()}</span>${equipped?'<span class="equipped-badge">장착 중</span>':`<span class="gear-slot-name">${slotFor(item).name}</span>`}</div><span class="gear-card-icon">${slotFor(item).icon}</span><strong>${gearName(item)}${item.enhance?` +${item.enhance}`:''}</strong><small>${formatEnhanced(item)}</small></button>`;}
function itemDetail(item,save,{battle,skills,units,ui}){
  if(!item)return `<div class="gear-detail-empty">${icon('grid')}<h3>장비를 선택하세요</h3><p>장비의 기본 능력과 랜덤 옵션,<br>현재 장비와의 차이를 확인할 수 있습니다.</p></div>`;
  const grade=GRADES[item.rarity],slot=slotFor(item),equipped=isEquipped(save,item.uid),current=save.gear.find(i=>i.uid===save.equipped[item.slot]);
  const otherValue=stat=>{if(!current)return 0;return [{...current.base,value:enhancedBase(current)},...current.affixes].filter(o=>o.stat===stat).reduce((n,o)=>n+(o.stat==='rate'?o.value/2:o.value),0);};
  const delta=(stat,value)=>{if(equipped)return '';if(stat==='rate')value/=2;const diff=value-otherValue(stat);const isPercent=['rate','ability','regen','speed','all'].includes(stat);return `<em class="${diff>0?'positive':diff<0?'negative':'neutral'}">${diff>0?'+':''}${Number((diff*(isPercent?100:1)).toFixed(1))}${isPercent?'%':''}</em>`;};
  const character=byId(CHARACTERS,save.character),before=applyUnitStats(calculateStats(save,character,skills),units),preview=applyUnitStats(calculateStats({...save,gear:save.gear.map(i=>i.uid===item.uid?{...i,location:'bag'}:i),equipped:{...save.equipped,[item.slot]:item.uid}},character,skills),units);
  return `<div class="gear-detail" style="--gear-color:${grade.color}"><div class="gear-detail-top"><span class="grade-label">${item.rarity.toUpperCase()} · ${grade.name}</span><span>${slot.name}</span></div><div class="gear-detail-title"><span>${slot.icon}</span><h3>${gearName(item)}${item.enhance?` +${item.enhance}`:''}</h3><small>${equipped?'현재 장착 중':item.location==='warehouse'?'창고 보관 중':'인벤토리 · 미장착'}</small></div><div class="gear-options"><span class="eyebrow">BASE / 고정 기본 옵션</span><p><span>${formatEnhanced(item)}</span>${delta(item.base.stat,enhancedBase(item))}</p><span class="eyebrow">AFFIXES / 획득 시 랜덤 수치</span>${item.affixes.map(a=>{const range=optionRange(a.stat,item.rarity),percent=['rate','ability','regen','speed'].includes(a.stat);return `<p><span>${formatOption(a.stat,a.value)}<small>범위 ${percent?pct(a.stat==='rate'?range[0]/2:range[0]):range[0]} – ${percent?pct(a.stat==='rate'?range[1]/2:range[1]):range[1]}</small></span>${delta(a.stat,a.value)}</p>`;}).join('')}</div>${item.extra?`<div class="gear-options"><span class="eyebrow">EPIC / 추가 옵션</span><p><span>${formatOption(item.extra.stat,item.extra.value)}<small>범위 ${extraRange(item.slot,item.rarity).map(v=>PERCENT_STATS.has(item.extra.stat)?pct(item.extra.stat==='rate'?v/2:v):v).join(' – ')}</small></span></p></div>`:''}${item.special?`<div class="unique-option"><strong>✦ ${UNIQUE_OPTIONS[item.slot].name}</strong><p>${UNIQUE_OPTIONS[item.slot].desc}</p>${item.rarity==='le'?`<p>LE 추가 · ${({weapon:'발사체 1개당 추가 발사체 +1',armor:'피해 감소 +50%p (최대 95%)',helmet:'시전형 초능력 횟수 +1',boots:'회피 재사용 대기시간 100% 감소',gloves:'적에게 피해를 줄 때 체력 2 회복',core:'초능력 강화 배율 +30%'})[item.slot]}</p>`:''}</div>`:''}${!equipped?`<details class="gear-comparison" open><summary>${current?`${gearName(current)} (${current.rarity.toUpperCase()}) 대비`:'빈 슬롯에 장착 시'} · 최종 능력치</summary><div>${STAT_ROWS.filter(([key])=>Math.abs(before[key]-preview[key])>.0001).map(([key,label])=>{const diff=preview[key]-before[key];return `<p><span>${label}</span><span>${statValue(key,before[key])} → <b class="${diff>0?'positive':'negative'}">${statValue(key,preview[key])}</b></span></p>`;}).join('')||'<p>전투 능력치 변화 없음</p>'}</div></details>`:''}<div class="gear-detail-actions">${equipped?`<button class="button secondary full-width" data-action="gear-unequip" data-id="${slot.id}">장착 해제</button>`:item.location==='bag'?`<button class="button primary full-width" data-action="gear-equip" data-id="${item.uid}">${current?'교체 장착':'장착하기'} ${icon('check')}</button>`:!battle?`<button class="button primary full-width" data-action="gear-move" data-id="${item.uid}" data-destination="bag">인벤토리로 꺼내기 ${icon('arrow')}</button>`:''}${!battle?`<div class="gear-management"><button class="button" data-action="gear-move" data-id="${item.uid}" data-destination="${item.location==='bag'?'warehouse':'bag'}" ${equipped?'disabled':''}>${item.location==='bag'?'창고 수납':'꺼내기'}</button><button class="button sell-button" data-action="gear-sell" data-id="${item.uid}" ${equipped?'disabled':''}>판매 · ${grade.sell} 에테르</button></div>${equipped?'<p class="gear-hint">판매·수납하려면 장착을 먼저 해제하세요.</p>':''}${item.location==='bag'?`<button class="button full-width" data-action="gear-enhance" data-id="${item.uid}" ${(item.enhance||0)>=10?'disabled':''}>${(item.enhance||0)>=10?'강화 MAX':`+${(item.enhance||0)+1} 강화 · ${ENHANCE_CHANCES[item.enhance||0]*100}% · ${(1000+500*(item.enhance||0)).toLocaleString()} 에테르`}</button><small class="gear-hint">실패 시 단계 유지 · +9 기본 옵션 +80% · +10 +100%</small><button class="button full-width" data-action="gear-reroll" data-id="${item.uid}">옵션 재설정 · ${REROLL_COST[item.rarity]} 에테르</button>${['uq','ep'].includes(item.rarity)?`<div class="craft-panel"><strong>${item.rarity==='uq'?'EP · 50% · 1,000':'LE · 30% · 3,000'} 에테르 제작</strong><small>같은 부위·등급의 미장착 재료 2개 · 실패 시 메인 유지</small>${craftMaterialsMarkup(save,item,ui.craftMaterials)}<button class="button full-width" data-action="gear-craft" data-id="${item.uid}" ${craftCandidates(save,item.uid).length<2?'disabled':''}>상위 장비 제작</button></div>`:''}`:''}`:'<p class="gear-hint">판매와 창고는 작전 본부에서 이용할 수 있습니다.</p>'}</div></div>`;
}
export function equipmentMarkup(save,ui,{battle=false,skills={},units={}}={}){
  if(battle)ui.tab='bag';
  const filtered=save.gear.filter(i=>i.location===ui.tab&&(ui.slot==='all'||i.slot===ui.slot)&&(ui.grade==='all'||i.rarity===ui.grade)).sort((a,b)=>GRADE_IDS.indexOf(b.rarity)-GRADE_IDS.indexOf(a.rarity)||Number(b.uid.slice(5))-Number(a.uid.slice(5)));
  const pages=Math.max(1,Math.ceil(filtered.length/12));ui.page=Math.min(pages-1,Math.max(0,ui.page));
  if(!filtered.some(i=>i.uid===ui.selected))ui.selected=filtered[0]?.uid||null;
  const selected=filtered.find(i=>i.uid===ui.selected),stats=applyUnitStats(calculateStats(save,byId(CHARACTERS,save.character),skills),units),reduction=damageReduction(save,stats,skills);
  return `<div class="equipment-layout"><section class="loadout-panel"><div class="gear-section-heading"><span class="eyebrow">LOADOUT</span><h3>장착 장비 <small>${Object.keys(save.equipped).length} / 6</small></h3><p>부위당 1개 · 장착한 옵션만 적용</p></div><div class="loadout-slots">${SLOTS.map(slot=>{const item=save.gear.find(i=>i.uid===save.equipped[slot.id]);return `<button class="loadout-slot ${item?'occupied':''}" data-action="gear-slot" data-id="${slot.id}" style="--gear-color:${item?GRADES[item.rarity].color:'#677875'}" aria-label="${slot.name} ${item?gearName(item):'빈 슬롯'}"><span>${slot.icon}</span><div><small>${slot.name}</small><strong>${item?gearName(item):'미장착'}</strong></div>${item?`<b>${item.rarity.toUpperCase()}</b>`:'<b>—</b>'}</button>`;}).join('')}</div><div class="loadout-stats"><span class="eyebrow">${battle?'현재 전투 능력':'출격 기본 능력'}</span>${STAT_ROWS.map(([key,label])=>`<p><span>${label}</span><b>${statValue(key,stats[key])}</b></p>`).join('')}<p><span>총 피해 감소</span><b>${pct(reduction.total)}</b></p></div>${statsHelp(stats,reduction)}</section><section class="inventory-panel"><div class="inventory-tabs"><button class="${ui.tab==='bag'?'active':''}" data-action="gear-tab" data-id="bag">인벤토리 <b>${save.gear.filter(i=>i.location==='bag').length}</b></button><button class="${ui.tab==='warehouse'?'active':''}" data-action="gear-tab" data-id="warehouse" ${battle?'disabled title="창고는 로비에서 이용할 수 있습니다"':''}>창고 <b>${save.gear.filter(i=>i.location==='warehouse').length}</b></button></div>${!battle&&ui.tab==='warehouse'?`<div class="bulk-sale"><button class="button" data-action="gear-auto-craft">창고 자동 합성</button><small>창고의 같은 부위·등급 UQ/EP 3개씩 합성합니다.</small></div>`:''}${!battle&&ui.tab==='bag'?`<div class="bulk-sale"><strong>장비 뽑기</strong>${[1,10,100].map(n=>`<button class="button" data-action="gear-draw" data-id="${n}">${n}회 · ${(n*1000).toLocaleString()} 에테르</button>`).join('')}<small>${Object.entries(drawRates()).map(([id,p])=>`${id.toUpperCase()} ${pct(p)}`).join(' · ')} · 자동 판매 설정 적용</small></div>`:''}<div class="gear-filters"><label>부위<select id="gear-slot-filter" aria-label="장비 부위 필터"><option value="all">전체 부위</option>${SLOTS.map(s=>`<option value="${s.id}" ${ui.slot===s.id?'selected':''}>${s.name}</option>`).join('')}</select></label><label>등급<select id="gear-grade-filter" aria-label="장비 등급 필터"><option value="all">전체 등급</option>${GRADE_IDS.map(id=>`<option value="${id}" ${ui.grade===id?'selected':''}>${id.toUpperCase()} · ${GRADES[id].name}</option>`).join('')}</select></label></div>${!battle&&ui.tab==='bag'?`<div class="bulk-sale"><label>판매 상한 등급 <select id="bulk-grade" aria-label="일괄 판매 상한 등급">${GRADE_IDS.map(id=>`<option value="${id}" ${ui.bulkGrade===id?'selected':''}>${id.toUpperCase()} 이하</option>`).join('')}</select></label><button class="button" data-action="gear-bulk">일괄 판매</button><button class="button" data-action="gear-auto">자동 판매: ${save.autoSellGrade?save.autoSellGrade.toUpperCase()+' 이하':'꺼짐'}</button><small>일괄 판매는 미장착 인벤토리만 · 자동 판매는 획득 시 선택 등급 이하 적용</small></div>`:''}<div class="gear-grid">${filtered.slice(ui.page*12,ui.page*12+12).map(i=>itemCard(i,save,ui)).join('')||`<div class="inventory-empty">${icon('grid')}<h3>${ui.tab==='warehouse'?'창고가 비어 있습니다':'표시할 장비가 없습니다'}</h3><p>${ui.tab==='warehouse'?'인벤토리에서 미장착 장비를 수납하세요.':'다른 필터를 선택하거나 전장에서 장비를 획득하세요.'}</p></div>`}</div><div class="gear-pagination"><span>${filtered.length}개 · 장비 수량 제한 없음</span><div><button data-action="gear-page" data-id="-1" aria-label="이전 장비 페이지" ${ui.page===0?'disabled':''}>‹</button><span>${ui.page+1} / ${pages}</span><button data-action="gear-page" data-id="1" aria-label="다음 장비 페이지" ${ui.page>=pages-1?'disabled':''}>›</button></div></div><div class="inventory-note">${icon('check')} 장비·장착 상태·창고는 자동 저장됩니다.<br>획득한 장비는 미장착 상태로 인벤토리에 들어옵니다.</div>${!battle?dropTable():''}</section><aside class="item-detail-panel">${itemDetail(selected,save,{battle,skills,units,ui})}</aside></div>`;
}
export function dropTable(){return `<details class="drop-table"><summary>구역별 장비 등급 확률</summary><p>장비가 드롭될 때의 확률 · 보스는 EL·SP·UQ 각각 2배 · EP·LE는 제작 또는 장비 뽑기에서 획득</p>${[false,true].map(boss=>`<div><h4>${boss?'보스 전리품':'일반 전리품'}</h4><table><thead><tr><th>구역</th>${GRADE_IDS.map(g=>`<th style="color:${GRADES[g].color}">${g.toUpperCase()}</th>`).join('')}</tr></thead><tbody>${STAGES.map(({id:stage})=>`<tr><th>${stage}</th>${Object.values(dropRates(stage,boss)).map(n=>`<td>${pct(n)}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`).join('')}<small>보스의 C·U 확률은 기존 비율을 유지하며 조정합니다. 표의 반올림으로 합계가 0.01% 차이날 수 있습니다.</small></details>`;}

export function craftMaterialsMarkup(save,item,selected=[]){
 const candidates=craftCandidates(save,item.uid),valid=selected.map(id=>candidates.some(i=>i.uid===id)?id:'');
 return [0,1].map(index=>`<label>재료 ${index+1}<select id="craft-${index+1}" aria-label="제작 재료 ${index+1}"><option value="">재료 선택</option>${candidates.filter(i=>i.uid!==valid[1-index]).map(i=>`<option value="${i.uid}" ${valid[index]===i.uid?'selected':''}>${gearName(i)} · ${i.rarity.toUpperCase()} · ${i.affixes.map(a=>formatOption(a.stat,a.value)).join(' / ')}</option>`).join('')}</select></label>`).join('');
}
